keys = ["apple", "mango", "zebra", "fig", "kiwi", "plum"]
bounds = ["g", "p"]
def part(k):
    for i, b in enumerate(bounds):
        if k < b: return i
    return len(bounds)
parts = {}
for k in keys: parts.setdefault(part(k), []).append(k)
for i in sorted(parts): print("partition %d:" % i, sorted(parts[i]))

