import hashlib
def hpart(key, n=4):
    return int(hashlib.md5(key.encode()).hexdigest(), 16) % n
keys = ["k%02d" % i for i in range(12)]
parts = {}
for k in keys: parts.setdefault(hpart(k), []).append(k)
for i in sorted(parts): print("partition %d: %d keys" % (i, len(parts[i])))

